import {comparisonGroup} from './v24-comparison.mjs';
import {esc as h,percent as p,metric,empty,formula} from './v15-ui.mjs';
const button=(act,text,id='',selected=false,disabled=false)=>`<button type="button" class="v15-button ${selected?'is-selected':''}" data-act="${act}" data-id="${h(id)}" ${disabled?'disabled':''}>${h(text)}</button>`;
export function peerGroupView(a,ui={}){
 const picker=`<label class="v15-fund-picker"><span>所持基金</span><select id="v7-analysis-fund">${a.funds.map(f=>`<option value="${h(f.id)}" ${f.id===a.fund.id?'selected':''}>${h(f.name)} · ${h(f.code)}</option>`).join('')}</select></label>`;
 const g=comparisonGroup(ui.comparisonCatalogue,a.fund.code,ui,a.fund.study.peers||[]);
 if(!g)return picker+empty(ui.comparisonError||'正在读取同类对照…',ui.comparisonError?button('reload-comparison','重新读取'):'');
 const scope=ui.peerScope||'type',rank=k=>{const x=g.statistics[k];return x.rank===null?'—':x.rank+' / '+x.n;},row=(x,label)=>`<tr class="${x.code===a.fund.code?'v24-target-row':''}"><th scope="row">${h(label||x.name)}${label?'':`<small>${h(x.code)} · ${h(x.family)}${x.code===a.fund.code?' · 所持':''}</small>`}</th>${['totalReturn','annualVol','maxDrawdown','ulcer','win63','fee'].map(k=>`<td>${p(x[k])}</td>`).join('')}<td>${label||x.code===a.fund.code?'':button('analysis-peer','深入对比',x.code)}</td></tr>`;
 const median=Object.fromEntries(Object.entries(g.statistics).map(([k,x])=>[k,x.median]));
 return `<div class="v24-group-top">${picker}<div class="v15-segments" aria-label="同类比较范围">${button('peer-scope','同类型全部','type',scope==='type')}${button('peer-scope','同指数','index',scope==='index',!g.target.indexCode)}${button('peer-scope','相似持仓','similar',scope==='similar',!a.fund.study.peers?.length)}</div></div>
 <div class="v24-group-controls"><label>比较区间<select id="v24-peer-horizon"><option value="year" ${g.period==='year'?'selected':''}>近252交易日</option><option value="long" ${g.period==='long'?'selected':''}>近三年</option></select></label><label>产品形式<select id="v24-peer-family">${[['all','全部'],['ETF','ETF'],['联接','联接'],['其他','其他']].map(([v,t])=>`<option value="${v}" ${(ui.peerFamily||'all')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>排序<select id="v24-peer-sort">${[['totalReturn','区间收益：高到低'],['maxDrawdown','回撤：浅到深'],['annualVol','波动：低到高'],['ulcer','回撤压力：低到高'],['fee','管理＋托管费率：低到高']].map(([v,t])=>`<option value="${v}" ${(ui.peerSort||'totalReturn')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>查找基金<input type="search" id="v24-peer-search" aria-label="查找同类基金" value="${h(ui.peerSearch||'')}" placeholder="基金名称或代码"></label></div>
 <p class="v15-scope-line">${h(g.target.type)} · ${h(g.window.from)} 至 ${h(g.window.to)} · ${h(g.window.observations)}个日收益</p>
 <div class="v15-stat-band">${metric('同类对照',g.comparisonCount+'个份额')}${metric('收益由高到低',rank('totalReturn'),'有同期指标份额中的名次')}${metric('回撤由浅到深',rank('maxDrawdown'),'有同期指标份额中的名次')}</div>
 <h3 class="v16-subtitle">本基金与同类中位数</h3><div class="v15-table-wrap"><table class="v15-table v24-group-table"><thead><tr>${['基金','区间收益','年化波动','最大回撤','回撤压力','63日盈利窗口占比','管理＋托管年费率',''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${row(g.target)}${row(median,'其他同类中位数')}</tbody></table></div>
 <h3 class="v16-subtitle">全部对照基金 <small>${g.filteredCount}个份额${ui.peerSearch?' · 按搜索筛选':''}</small></h3><div class="v15-table-wrap"><table class="v15-table v24-group-table"><thead><tr>${['基金','区间收益','年化波动','最大回撤','回撤压力','63日盈利窗口占比','管理＋托管年费率',''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${g.visible.slice(1).map(x=>row(x)).join('')}</tbody></table></div>${g.filteredCount?'':'<p class="v8-muted">未找到匹配基金。</p>'}
 <div class="v24-group-pagination">${button('peer-page','上一页',String(g.page-1),false,g.page===0)}<span>${g.page+1} / ${g.pages}</span>${button('peer-page','下一页',String(g.page+1),false,g.page+1===g.pages)}</div>
 ${formula('同类型使用基金公开分类，产品形式可进一步筛选；同指数按已登记指数代码匹配。每个份额单独比较。收益、波动、回撤和63交易日滚动窗口统一取所选起止日，覆盖完整区间后参与统计。其他同类中位数剔除本基金；各指标分别使用有数值的份额，排序和名次基于完整比较组，搜索与翻页只改变表格展示。并列使用相同名次。年费率统一比较管理费与托管费。盈利窗口占比描述所选历史起点的结果分布。','分组与统计方法')}`;
}
